    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Past Continuous Questions with Was and Were';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Past Continuous Questions with Was and Were','Move was/were before the subject and use question words to ask about past scenes.','Objective: Ask and answer yes/no and wh- questions about actions in progress at a past time.
Content: For a yes/no question, put was or were before the subject: Were they working? For a wh- question, put the question word first: What was she carrying? Keep the main verb in the -ing form.
Examples:
- Were you waiting at the station?
- What was Nam doing at six?
- Why were they laughing?
Common errors and corrections:
- Do not add did to a was/were question: Was she cooking?
- Keep -ing after was/were: What were they doing?
Guided practice: Find the subject and auxiliary, then place was/were before the subject in questions.
Summary: Past continuous questions begin with was/were, or a wh-word followed by was/were and the subject.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Past Continuous Questions with Was and Were','Move was/were before the subject and use question words to ask about past scenes.','Objective: Ask and answer yes/no and wh- questions about actions in progress at a past time.
Content: For a yes/no question, put was or were before the subject: Were they working? For a wh- question, put the question word first: What was she carrying? Keep the main verb in the -ing form.
Examples:
- Were you waiting at the station?
- What was Nam doing at six?
- Why were they laughing?
Common errors and corrections:
- Do not add did to a was/were question: Was she cooking?
- Keep -ing after was/were: What were they doing?
Guided practice: Find the subject and auxiliary, then place was/were before the subject in questions.
Summary: Past continuous questions begin with was/were, or a wh-word followed by was/were and the subject.','GRAMMAR',2,10,FALSE) RETURNING id INTO v_lesson_revision_id;
