    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Interrupted Events with When';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Interrupted Events with When','Use past continuous for the background action and past simple for the interrupting event.','Objective: Combine a longer action in progress with a shorter completed event using when.
Content: Use past continuous for an action already in progress and past simple for a shorter event that interrupts it. When often introduces the shorter event: I was walking home when it started to rain. The order of the clauses can change without changing the meaning.
Examples:
- She was cooking when the phone rang.
- When the lights went out, we were watching a film.
- They were crossing the road when the bus stopped.
Common errors and corrections:
- Do not use past continuous for both actions when one short event interrupts another.
- The verb after when can be past simple for the interrupting event.
Guided practice: Mark the longer background action and the shorter event, then choose the tense for each.
Summary: Use past continuous for the action in progress and past simple for the event that interrupts it.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Interrupted Events with When','Use past continuous for the background action and past simple for the interrupting event.','Objective: Combine a longer action in progress with a shorter completed event using when.
Content: Use past continuous for an action already in progress and past simple for a shorter event that interrupts it. When often introduces the shorter event: I was walking home when it started to rain. The order of the clauses can change without changing the meaning.
Examples:
- She was cooking when the phone rang.
- When the lights went out, we were watching a film.
- They were crossing the road when the bus stopped.
Common errors and corrections:
- Do not use past continuous for both actions when one short event interrupts another.
- The verb after when can be past simple for the interrupting event.
Guided practice: Mark the longer background action and the shorter event, then choose the tense for each.
Summary: Use past continuous for the action in progress and past simple for the event that interrupts it.','GRAMMAR',3,10,FALSE) RETURNING id INTO v_lesson_revision_id;
