    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='When and While in Short Narratives';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'When and While in Short Narratives','Use while to frame an action in progress and when to introduce a past event or time point.','Objective: Choose when or while and combine past continuous with past simple in short narratives.
Content: While commonly introduces the longer action in progress: While I was studying, my friend called. When often introduces the shorter event: I was studying when my friend called. Past continuous can also describe two actions happening at the same time, but this lesson focuses on clear A2 narratives.
Examples:
- While Mum was driving, I was reading the map.
- I dropped my keys while I was opening the door.
- We were talking when the manager arrived.
Common errors and corrections:
- Use while with an action in progress when the context calls for a background action.
- Do not change the short interrupting event to past continuous unless the meaning is also an action in progress.
Guided practice: Read each two-event situation, identify the background and interrupting event, then connect them with when or while.
Summary: When and while connect past events; use past continuous for the background action and past simple for a short completed event.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'When and While in Short Narratives','Use while to frame an action in progress and when to introduce a past event or time point.','Objective: Choose when or while and combine past continuous with past simple in short narratives.
Content: While commonly introduces the longer action in progress: While I was studying, my friend called. When often introduces the shorter event: I was studying when my friend called. Past continuous can also describe two actions happening at the same time, but this lesson focuses on clear A2 narratives.
Examples:
- While Mum was driving, I was reading the map.
- I dropped my keys while I was opening the door.
- We were talking when the manager arrived.
Common errors and corrections:
- Use while with an action in progress when the context calls for a background action.
- Do not change the short interrupting event to past continuous unless the meaning is also an action in progress.
Guided practice: Read each two-event situation, identify the background and interrupting event, then connect them with when or while.
Summary: When and while connect past events; use past continuous for the background action and past simple for a short completed event.','GRAMMAR',4,10,FALSE) RETURNING id INTO v_lesson_revision_id;
